                pronunciationBn = "আদদু‘আ-উ হুওয়াল ‘ইবা-দাহ... ওয়া ক্বালা রব্বুকুমুদ‘ঊনী আস্তাজিব লাকুম।",
                meaningBn = "১. দো‘আ হলো মূল ইবাদত: রাসূলুল্লাহ ﷺ বলেন: ‘দো‘আ-ই হলো ইবাদত।’ (তিরমিযী: ২৯৬৯)\nমহান আল্লাহ বলেন: ‘তোমরা আমাকে ডাকো, আমি তোমাদের ডাকে সাড়া দেব।’ (সূরা গাফির: ৬০)\nনবীজী ﷺ আরও বলেন: ‘যে ব্যক্তি আল্লাহর কাছে চায় না, তিনি তার ওপর ক্রুদ্ধ হন।’ (তিরমিযী: ৩৩৭৩)\n\n২. দু'আ কবুল হওয়ার ৩টি পদ্ধতি (হযরত আবু সাঈদ খুদরী রা. বর্ণিত):\nকোনো মুসলিম যখন কোনো পাপ বা আত্মীয়তার সম্পর্ক ছিন্ন করা ব্যতীত দু'আ করে, আল্লাহ তাকে তিনটির যেকোনো একটি দান করেন:\n(১) তার দু'আ দুনিয়াতেই সরাসরি কবুল করেন, অথবা\n(২) তার প্রতিদান আখেরাতের জন্য স্থায়ী সঞ্চয় হিসেবে জমা রাখেন, অথবা\n(৩) তার সমপরিমাণ অন্য কোনো আসন্ন অনিষ্ট বা বিপদ তার থেকে দূর করে দেন।\nসাহাবীগণ বললেন: ‘তাহলে তো আমরা বেশি বেশি দু'আ করব!’ নবীজী ﷺ বললেন: ‘আল্লাহর ভাণ্ডার তার চেয়েও বহুগুণ অসীম!’\n\n৩. দু'আ কবুলের ৭টি আবশ্যিক শর্ত:\n(১) খাদ্য, পানীয় ও পোশাক হালাল উপার্জন থেকে হওয়া (হারাম ভক্ষণকারীর দো‘আ আসমানে প্রত্যাখ্যাত হয়)।\n(২) শুধুমাত্র আল্লাহর সন্তুষ্টির জন্য একনিষ্ঠ নিয়ত হওয়া।\n(৩) দু'আয় কোনো গুনাহ বা আত্মীয়তার সম্পর্কচ্ছেদের বিষয় না থাকা।\n(৪) শুরুতে আল্লাহর হামদ ও রাসূল ﷺ-এর উপর দরূদ পাঠ করা।\n(৫) দু'আ কবুলের জন্য তাড়াহুড়ো না করা (‘দোয়া করলাম কবুল হলো না’ বলে নিরাশ না হওয়া)।\n(৬) উদাসীন হৃদয়ে দু'আ না করে দৃঢ় প্রত্যয় ও গভীর আশা রাখা।\n(৭) দো‘আ ছেড়ে না দিয়ে নিয়মিত চেয়ে যাওয়া।",
                fojilotBn = "হালাল জীবিকা ও একনিষ্ঠ অন্তরে আল্লাহর কাছে চাইলে কোনো দো'আই ব্যর্থ হয় না; প্রতিদান নিশ্চিতভাবে বান্দার কাছে ফিরে আসে।",
